package com.bank.batch.service;

import com.bank.batch.model.Payment;
import com.bank.batch.repository.PaymentRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.List;

@Service
@RequiredArgsConstructor
@Slf4j
public class BatchPaymentService {

    private final PaymentRepository paymentRepo;
    private final PaymentValidatorBad badValidator;
    private final PaymentValidatorGood goodValidator;

    /**
     * BAD: catches exception but TX is already rollback-only → UnexpectedRollbackException!
     *
     * Sequence:
     * 1. Outer TX begins (REQUIRED — creates new TX)
     * 2. PAY-001: validate → OK. markProcessed.
     * 3. PAY-002: validate → THROWS! Inner REQUIRED marks SHARED TX as rollback-only.
     *    Outer catches exception. Tries to continue.
     * 4. PAY-003: validate → OK. markProcessed.
     * 5. Outer TX commits → FAILS! TX was marked rollback-only by step 3.
     *    → UnexpectedRollbackException
     *    → ALL 3 payments LOST (including valid PAY-001 and PAY-003)!
     */
    @Transactional
    public int processWithBadValidator() {
        List<Payment> pending = paymentRepo.findByStatus("PENDING");
        int processed = 0;

        for (Payment payment : pending) {
            try {
                badValidator.validate(payment.getAccountId());  // REQUIRED — shares this TX
                payment.markProcessed();
                paymentRepo.save(payment);
                processed++;
            } catch (Exception e) {
                // Caught the exception — but the TX is ALREADY marked rollback-only!
                log.warn("Caught exception for {}: {} — but TX may be poisoned!",
                    payment.getPaymentId(), e.getMessage());
                payment.markFailed(e.getMessage());
                paymentRepo.save(payment);
            }
        }

        log.info("Processed {} payments — but commit may fail due to rollback-only!", processed);
        return processed;
        // COMMIT → UnexpectedRollbackException! ALL work lost.
    }

    /**
     * GOOD: inner uses REQUIRES_NEW → failure is isolated → outer TX safe.
     */
    @Transactional
    public int processWithGoodValidator() {
        List<Payment> pending = paymentRepo.findByStatus("PENDING");
        int processed = 0;

        for (Payment payment : pending) {
            try {
                goodValidator.validate(payment.getAccountId());  // REQUIRES_NEW — own TX
                payment.markProcessed();
                paymentRepo.save(payment);
                processed++;
            } catch (Exception e) {
                // Inner TX rolled back independently. Outer TX is SAFE.
                log.info("Skipped {}: {} — outer TX still healthy",
                    payment.getPaymentId(), e.getMessage());
                payment.markFailed(e.getMessage());
                paymentRepo.save(payment);
            }
        }

        log.info("Processed {} payments — commit will succeed!", processed);
        return processed;
        // COMMIT → SUCCESS! PAY-001 and PAY-003 processed, PAY-002 failed.
    }
}
