package com.bank.batch.controller;

import com.bank.batch.service.BatchPaymentService;
import lombok.RequiredArgsConstructor;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/v1/batch")
@RequiredArgsConstructor
public class BatchController {

    private final BatchPaymentService batchService;

    @PostMapping("/process-bad")
    public String processBad() {
        try {
            int count = batchService.processWithBadValidator();
            return "Processed: " + count;
        } catch (Exception e) {
            return "FAILED: " + e.getClass().getSimpleName() + " — " + e.getMessage();
        }
    }

    @PostMapping("/process-good")
    public String processGood() {
        int count = batchService.processWithGoodValidator();
        return "Processed: " + count;
    }
}
