package com.bank.batch.service;

import com.bank.batch.model.Payment;
import com.bank.batch.repository.PaymentRepository;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.*;
import org.mockito.junit.jupiter.MockitoExtension;
import java.util.List;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;

@ExtendWith(MockitoExtension.class)
class BatchPaymentServiceTest {

    @Mock PaymentRepository paymentRepo;
    @Mock PaymentValidatorGood goodValidator;
    @Mock PaymentValidatorBad badValidator;
    @InjectMocks BatchPaymentService batchService;

    @Test
    void shouldProcessValidPaymentsWithGoodValidator() {
        Payment valid = mock(Payment.class);
        when(valid.getAccountId()).thenReturn("SAV2001");
        when(valid.getPaymentId()).thenReturn("PAY-001");
        when(paymentRepo.findByStatus("PENDING")).thenReturn(List.of(valid));

        int count = batchService.processWithGoodValidator();

        assertThat(count).isEqualTo(1);
        verify(valid).markProcessed();
    }

    @Test
    void shouldSkipInvalidAndContinueWithGoodValidator() {
        Payment invalid = mock(Payment.class);
        when(invalid.getAccountId()).thenReturn("INVALID");
        when(invalid.getPaymentId()).thenReturn("PAY-002");
        doThrow(new RuntimeException("Invalid")).when(goodValidator).validate("INVALID");

        Payment valid = mock(Payment.class);
        when(valid.getAccountId()).thenReturn("CUR3001");
        when(valid.getPaymentId()).thenReturn("PAY-003");

        when(paymentRepo.findByStatus("PENDING")).thenReturn(List.of(invalid, valid));

        int count = batchService.processWithGoodValidator();

        assertThat(count).isEqualTo(1);  // only valid processed
        verify(invalid).markFailed("Invalid");
        verify(valid).markProcessed();
    }
}
